    mov     d1, a1
    clr     d2
    mov     5, d3
    add     a2, d3
    setlb
    extbu   d0
    mov     d0, d1
    asl2    d1
    add     d0, d1
    add     d3, d1
    mov     d1, a0
    mov     a1, d0
